changeSet.sql:
ALTER TABLE nexus.catalog_documents
    ADD COLUMN sensitive BOOLEAN NOT NULL DEFAULT false;

CREATE INDEX idx_catalog_documents_sensitive_live
    ON nexus.catalog_documents (tenant_id, physical_collection)
    WHERE sensitive AND deleted_at IS NULL;

CREATE TABLE nexus.catalog_sensitivity_changes (
    id         BIGSERIAL   NOT NULL,
    tenant_id  TEXT        NOT NULL,
    tumbler    TEXT        NOT NULL,
    old        BOOLEAN     NOT NULL,
    new        BOOLEAN     NOT NULL,
    reason     TEXT        NOT NULL,
    actor      TEXT        NOT NULL,
    changed_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT catalog_sensitivity_changes_pk PRIMARY KEY (id)
);

CREATE INDEX idx_catalog_sensitivity_changes_doc
    ON nexus.catalog_sensitivity_changes (tenant_id, tumbler, changed_at);

ALTER TABLE nexus.catalog_sensitivity_changes ENABLE ROW LEVEL SECURITY;
ALTER TABLE nexus.catalog_sensitivity_changes FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON nexus.catalog_sensitivity_changes
    USING      (tenant_id = current_setting('nexus.tenant', true))
    WITH CHECK (tenant_id = current_setting('nexus.tenant', true));

CREATE OR REPLACE FUNCTION nexus.chunk_sensitive( p_tenant text, p_collection text, p_chash bytea ) RETURNS boolean LANGUAGE sql STABLE SECURITY INVOKER AS $$ SELECT EXISTS ( SELECT 1 FROM nexus.catalog_document_chunks m JOIN nexus.catalog_documents d ON d.tenant_id = m.tenant_id AND d.tumbler = m.doc_id WHERE m.tenant_id = p_tenant AND m.collection = p_collection AND m.chash = p_chash AND d.deleted_at IS NULL AND d.sensitive ) $$;
CREATE OR REPLACE FUNCTION nexus.chunk_sensitive_many( p_tenant text, p_collection text, p_chashes bytea[] ) RETURNS TABLE(chash bytea, sensitive boolean) LANGUAGE sql STABLE SECURITY INVOKER AS $$ SELECT u.h, EXISTS ( SELECT 1 FROM nexus.catalog_document_chunks m JOIN nexus.catalog_documents d ON d.tenant_id = m.tenant_id AND d.tumbler = m.doc_id WHERE m.tenant_id = p_tenant AND m.collection = p_collection AND m.chash = u.h AND d.deleted_at IS NULL AND d.sensitive ) FROM unnest(p_chashes) WITH ORDINALITY AS u(h, ord) ORDER BY u.ord $$;
GRANT EXECUTE ON FUNCTION nexus.chunk_sensitive(text, text, bytea) TO nexus_svc; GRANT EXECUTE ON FUNCTION nexus.chunk_sensitive_many(text, text, bytea[]) TO nexus_svc;

rollback.sql:
REVOKE EXECUTE ON FUNCTION nexus.chunk_sensitive_many(text, text, bytea[]) FROM nexus_svc;
REVOKE EXECUTE ON FUNCTION nexus.chunk_sensitive(text, text, bytea) FROM nexus_svc;
DROP FUNCTION IF EXISTS nexus.chunk_sensitive_many(text, text, bytea[]);
DROP FUNCTION IF EXISTS nexus.chunk_sensitive(text, text, bytea);
